import{_ as a,o as n,c as e,a2 as i}from"./chunks/framework.CdvW4CUT.js";const d=JSON.parse('{"title":"PXE - iPXE","description":"","frontmatter":{},"headers":[],"relativePath":"notes/hardware/firmware-boot/pxe_ipxe.md","filePath":"notes/hardware/firmware-boot/pxe_ipxe.md"}'),p={name:"notes/hardware/firmware-boot/pxe_ipxe.md"};function r(l,s,t,o,b,h){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="pxe-ipxe" tabindex="-1">PXE - iPXE <a class="header-anchor" href="#pxe-ipxe" aria-label="Permalink to &quot;PXE - iPXE&quot;">​</a></h1><p>类比<a href="./../../linux-kernel/boot/system_boot">system_boot</a>中提到的系统启动方式。<br> PXE与iPXE启动Linux安装环境时，最终需要的Kernel、initramfs和安装RootFS通常没有本质区别；<br> 区别主要集中在谁承担网络Bootloader角色、如何获取启动配置、支持哪些网络协议，以及是否需要额外链式加载GRUB。<br> 网络传输改变的是这些文件的来源和装载方式，而不是Kernel与initramfs进入内存后的执行机制。</p><h2 id="pxe-boot" tabindex="-1">PXE boot <a class="header-anchor" href="#pxe-boot" aria-label="Permalink to &quot;PXE boot&quot;">​</a></h2><h3 id="uefi" tabindex="-1">uefi <a class="header-anchor" href="#uefi" aria-label="Permalink to &quot;uefi&quot;">​</a></h3><p>当选择通过pxe引导时，uefi firmware会尝试通过网卡向dhcp服务器发送请求，获取ip地址、网关、dns、tftp服务器ip地址等信息。<br> dhcp服务器在响应dhcp请求时，会在响应中包含tftp服务器的ip地址和引导⽂件的名称和路径等信息</p><h3 id="shim" tabindex="-1">shim <a class="header-anchor" href="#shim" aria-label="Permalink to &quot;shim&quot;">​</a></h3><p>uefi 尝试向 tftp 服务器获取 shim.efi（在这里是 bootx64.efi）。 有关 shim.efi 的功能，详见 <a href="./../../linux-kernel/boot/system_boot">system_boot</a> 中有关 shim 一节。 在这里，bootx64.efi 将从 tftp 服务器获取对应的 grub.efi 文件。</p><p>NBP, Network Bootstrap Program，网络引导程序。<br> 它是客户端在PXE启动过程中通过网络下载并执行的第一个可执行文件，其作用是接替固件中能力有限的PXE环境，继续加载启动配置、Kernel和initramfs，或者链式加载另一个Bootloader。</p><h3 id="bootloader" tabindex="-1">bootloader <a class="header-anchor" href="#bootloader" aria-label="Permalink to &quot;bootloader&quot;">​</a></h3><p>和在本地引导一样，当 grub 完成必要的初始化时，将尝试解析 grub.cfg 文件。 只不过此时 client 需要从 tftp 服务器获取对应的 grub.cfg 文件。 后续 grub 也需要将对应的 kernel 和 initramfs 载入内存，只不过此时这些文件的来源是 tftp 服务器，而非本地。当成功载入 kernel 与 initramfs，并且一号进程启动后，就可以通过网络向 tftp 服务器获取系统文件，并安装系统。</p><p>PXE通常先由UEFI或网卡PXE固件通过DHCP获得客户端地址、TFTP服务器地址和NBP文件名，再通过TFTP下载并执行NBP，例如grubx64.efi、pxelinux.0或其他网络启动加载程序；<br> NBP随后读取配置，继续获取Kernel和initramfs。<br> PXE所定义的主要是“如何发现网络启动服务器并取得第一个可执行程序”，并不重新定义Linux Kernel和initramfs的内容.</p><p>总体流程：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统PXE：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>UEFI/PXE Firmware</span></span>
<span class="line"><span>    ↓ DHCP</span></span>
<span class="line"><span>获得IP地址、TFTP服务器和NBP文件名</span></span>
<span class="line"><span>    ↓ TFTP</span></span>
<span class="line"><span>下载grubx64.efi或pxelinux.0</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>读取GRUB/PXELINUX配置</span></span>
<span class="line"><span>    ↓ TFTP或其他协议</span></span>
<span class="line"><span>下载Kernel和initramfs</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Kernel执行initramfs中的/init</span></span>
<span class="line"><span>    ↓ HTTP/NFS/NBD</span></span>
<span class="line"><span>访问安装RootFS或软件包仓库</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p><img src="https://raw.githubusercontent.com/sandyyyz/Image-hosting/main/img/pxe_process.png" alt="pxe_boot_process"></p><h2 id="ipxe-boot" tabindex="-1">iPXE boot <a class="header-anchor" href="#ipxe-boot" aria-label="Permalink to &quot;iPXE boot&quot;">​</a></h2><p>iPXE可以看作功能更强的网络启动程序。它既可以直接集成到网卡或固件中，也可以由原生PXE先通过TFTP下载，再通过chainload执行。<br> 进入iPXE后，通常使用iPXE脚本直接描述Kernel、initramfs和命令行的位置，并通过HTTP、HTTPS、FTP、iSCSI等协议获取这些内容。<br> 一个 .ipxe 脚本：</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!ipxe</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kernel</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://server/linux/vmlinuz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">initrd=initrd.img </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">inst.repo=http://server/repo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">initrd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://server/linux/initrd.img</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boot</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>此时，iPXE相当于直接承担了网络bootloader的工作。此时的启动流程为：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UEFI → PXE Firmware → iPXE → Kernel → initramfs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>当然，iPXE也可以加载grubx64.efi, 此时的启动流程为：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UEFI → PXE Firmware → iPXE → GRUB → Kernel → initramfs</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>Q: 安装 rootfs 不一定一次性完整下载到内存？</p><p>PXE 和 iPXE 是两种允许计算机通过网络远程加载并启动系统的协议。相较于从本地加载启动系统，这二者主要改变了文件的数据来源和装载方式，并没有改变装载 initramfs 和 kernel 之后的行为。</p><p>与此同时，这二者还有不同：</p><ol><li>第一，初始网络启动程序不同。传统 PXE 必须先取得一个 NBP，可能是 grubx64.efi 或 pxelinux.0；iPXE 场景通常需要 ipxe.efi 或其他 iPXE 构建产物，除非 iPXE 已经集成在固件中。因此，最终 Kernel 和 initramfs 可以相同，但前置启动文件不完全相同。</li><li>第二，配置文件形式不同。GRUB 一般读取 grub.cfg，iPXE 则执行 .ipxe 脚本。它们表达的信息基本相同，都是 Kernel 位置、initramfs 位置和 Kernel Command Line，但语法和执行模型不同。</li></ol>`,26)])])}const m=a(p,[["render",r]]);export{d as __pageData,m as default};
